"""CI-only diagnostics contracts for guest and container JVM boundaries."""
import os
from pathlib import Path
import subprocess
import tempfile
import textwrap
import unittest
from unittest.mock import patch

from runner_common import create_seed_iso


class CiJvmDiagnosticsTests(unittest.TestCase):
    def render(self, root, enabled):
        environment = dict(os.environ)
        environment.pop("RDF4J_CI_JVM_DIAGNOSTIC_OPTIONS", None)
        if enabled:
            environment["RDF4J_CI_JVM_DIAGNOSTIC_OPTIONS"] = "host-only diagnostics"
        def build(command, log_path):
            Path(command[2]).write_bytes(b"iso")
        with patch.dict(os.environ, environment, clear=True), patch("runner_common.run_checked", side_effect=build):
            create_seed_iso(Path("genisoimage"), root, "test", "boot-writer.sh", builder="genisoimage")
        return (root / "test-seed/user-data").read_text()

    def test_local_seed_keeps_diagnostics_disabled(self):
        with tempfile.TemporaryDirectory() as temporary:
            rendered = self.render(Path(temporary), False)
            self.assertNotIn("HeapDumpOnOutOfMemoryError", rendered)
            self.assertNotIn("@JVM_DIAGNOSTICS@", rendered)

    def test_ci_seed_exports_guest_paths_and_unique_directory_each_boot(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            rendered = self.render(root, True)
            self.assertIn("-XX:+HeapDumpOnOutOfMemoryError", rendered)
            self.assertIn("-XX:HeapDumpGzipLevel=1", rendered)
            self.assertNotIn("host-only diagnostics", rendered)
            script = textwrap.dedent(rendered.split("    content: |\n", 1)[1].split("runcmd:", 1)[0])
            script = "\n".join(line for line in script.splitlines() if not line.startswith("mount "))
            script = script.replace("/mnt/run-results", str(root / "results"))
            script = script.replace("/mnt/rdf4j-ro", str(root / "repo")).replace("/mnt/m2-ro", str(root / "m2"))
            script = script[:script.index("exec bash")] + 'printf "%s\\n" "$JAVA_TOOL_OPTIONS"\n'
            env = dict(os.environ, JAVA_TOOL_OPTIONS="-Dexisting=preserved")
            first = subprocess.check_output(["bash", "-c", script], env=env, text=True)
            second = subprocess.check_output(["bash", "-c", script], env=env, text=True)
            self.assertNotEqual(first, second)
            self.assertIn("-Dexisting=preserved", first)
            self.assertIn("java_pid%p.hprof.gz", first)
            self.assertIn("hs_err_pid%p.log", first)
            self.assertEqual(len(list((root / "results/jvm-diagnostics").iterdir())), 2)

    def test_elasticsearch_containers_preserve_flags_and_bind_ci_output(self):
        root = Path(__file__).resolve().parents[2]
        paths = [root / "compliance/elasticsearch/src/test/java/org/eclipse/rdf4j/sail/elasticsearch/AbstractElasticsearchTest.java",
                 root / "core/sail/elasticsearch-store/src/test/java/org/eclipse/rdf4j/sail/elasticsearchstore/ElasticsearchStoreTestContainerSupport.java"]
        for path in paths:
            with self.subTest(path=path):
                source = path.read_text()
                self.assertIn('System.getenv("RDF4J_JVM_DIAGNOSTICS_DIR")', source)
                self.assertIn('Files.createTempDirectory(', source)
                self.assertIn('BindMode.READ_WRITE', source)
                self.assertIn('getEnvMap().getOrDefault("JAVA_TOOL_OPTIONS", "")', source)
                self.assertIn('getEnvMap().getOrDefault("ES_JAVA_OPTS", "")', source)
                self.assertIn('-XX:+HeapDumpOnOutOfMemoryError', source)
                self.assertIn('-XX:HeapDumpPath=', source)
                self.assertIn('-Xms512m -Xmx512m', source)
                self.assertNotIn('IgnoreUnrecognizedVMOptions', source)


if __name__ == "__main__":
    unittest.main()
